TASKS = {"A": {"prio": 2, "period": 5, "cost": 1, "budget": 1},
         "B": {"prio": 1, "period": 10, "cost": 3, "budget": 3}}

def run(protect):
    ready, used, line = {}, {}, []
    for t in range(30):
        for n, c in TASKS.items():
            if t % c["period"] == 0:
                ready[n] = 6 if (n == "B" and t == 20) else c["cost"]
                used[n] = 0
        if not ready:
            line.append("."); continue
        n = max(ready, key=lambda k: TASKS[k]["prio"])
        ready[n] -= 1; used[n] += 1; line.append(n)
        if protect and used[n] >= TASKS[n]["budget"] and ready[n] > 0:
            print(f"  t={t}ms ProtectionHook: {n} 예산 초과 -> 강제 종료")
            del ready[n]
        elif ready[n] == 0:
            del ready[n]
    return "".join(line)

print("보호 없음:", run(False))
print("보호 있음:", run(True))
# 보호 없음: ABBB.A....ABBB.A....ABBBBABB..
#   t=23ms ProtectionHook: B 예산 초과 -> 강제 종료
# 보호 있음: ABBB.A....ABBB.A....ABBB.A....
